    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 94-year-old female is evaluated for progressive gait instability, cognitive decline, and urinary urgency/incontinence over the past 2 months. Physical exam reveals a **apraxic (magnetic)** gait pattern. Brain MRI shows **ventriculomegaly** out of proportion to cortical sulcal atrophy. Which of the following is the most appropriate next diagnostic step?', '["Emergent external ventricular drain placement due to acute obstructive hydrocephalus", "Trial of high-dose furosemide to reduce CSF production and relieve ventricular pressure", "Large-volume lumbar puncture (removing 30-50 mL CSF) with pre- and post-procedure gait assessment and cognitive testing \u2014 improvement predicts successful treatment with ventriculoperitoneal (VP) shunt placement", "Initiation of high-dose levodopa/carbidopa for 6 months before considering any surgical intervention", "Brain biopsy of the periventricular region to rule out lymphoma or gliomatosis cerebri"]'::jsonb, 2, 'This patient presents with the classic triad of **Normal Pressure Hydrocephalus (NPH)** — ''''wet, wobbly, and wacky'''': (1) **Gait disturbance** (typically the earliest and most prominent symptom) — characteristically a **magnetic** gait (feet seem glued to the floor), broad-based, with short shuffling steps; (2) **Cognitive decline** — subcortical pattern with executive dysfunction, psychomotor slowing, and impaired attention; (3) **Urinary incontinence** — typically urgency-type initially, progressing to frank incontinence. MRI shows **ventriculomegaly** (Evans'''' index >0.3) **disproportionate to sulcal atrophy** (distinguishing it from ex-vacuo hydrocephalus of neurodegeneration). The diagnostic and prognostic test is a **large-volume LP** (''''tap test''''), removing 30-50 mL of CSF and measuring gait speed and cognition before and after. Improvement in gait (the most responsive symptom) predicts a favorable response to definitive treatment: **VP shunt placement**. NPH is one of the few **reversible causes of dementia** if diagnosed early. (Ref: Hazzard''''s Ch. 72; AGS Geriatrics At Your Fingertips)'),
    (v_topic_id, 'A 91-year-old female is evaluated for progressive gait instability, cognitive decline, and urinary urgency/incontinence over the past 3 months. Physical exam reveals a **apraxic (magnetic)** gait pattern. Brain MRI shows **ventriculomegaly** out of proportion to cortical sulcal atrophy. Which of the following is the most appropriate next diagnostic step?', '["Trial of high-dose furosemide to reduce CSF production and relieve ventricular pressure", "Large-volume lumbar puncture (removing 30-50 mL CSF) with pre- and post-procedure gait assessment and cognitive testing \u2014 improvement predicts successful treatment with ventriculoperitoneal (VP) shunt placement", "Initiation of high-dose levodopa/carbidopa for 6 months before considering any surgical intervention", "Brain biopsy of the periventricular region to rule out lymphoma or gliomatosis cerebri", "Emergent external ventricular drain placement due to acute obstructive hydrocephalus"]'::jsonb, 1, 'This patient presents with the classic triad of **Normal Pressure Hydrocephalus (NPH)** — ''''wet, wobbly, and wacky'''': (1) **Gait disturbance** (typically the earliest and most prominent symptom) — characteristically a **magnetic** gait (feet seem glued to the floor), broad-based, with short shuffling steps; (2) **Cognitive decline** — subcortical pattern with executive dysfunction, psychomotor slowing, and impaired attention; (3) **Urinary incontinence** — typically urgency-type initially, progressing to frank incontinence. MRI shows **ventriculomegaly** (Evans'''' index >0.3) **disproportionate to sulcal atrophy** (distinguishing it from ex-vacuo hydrocephalus of neurodegeneration). The diagnostic and prognostic test is a **large-volume LP** (''''tap test''''), removing 30-50 mL of CSF and measuring gait speed and cognition before and after. Improvement in gait (the most responsive symptom) predicts a favorable response to definitive treatment: **VP shunt placement**. NPH is one of the few **reversible causes of dementia** if diagnosed early. (Ref: Hazzard''''s Ch. 72; AGS Geriatrics At Your Fingertips)'),
